/* ===== part 3d: Spanish option (hub only; the study labs stay as they are) ===== */
let LANG='en';
try{LANG=((JSON.parse(localStorage.getItem(MPK)||'{}').set)||{}).lang==='es'?'es':'en'}catch(e){}
let ES_MAP=null,ES_RE=null;const esCache=new Map();
function esBuild(){ES_MAP=new Map(ES_PAIRS);const keys=[...ES_MAP.keys()].sort((a,b)=>b.length-a.length);ES_RE=new RegExp('(?<![A-Za-z])(?:'+keys.map(k=>k.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+')(?![A-Za-z])','g')}
function tr(s){if(LANG!=='es'||!s||!ES_RE||!/[A-Za-z]/.test(s))return s;let r=esCache.get(s);if(r!==undefined)return r;r=s.replace(ES_RE,m=>ES_MAP.get(m)||m);if(esCache.size>4000)esCache.clear();esCache.set(s,r);esCache.set(r,r);return r}
function esNode(n){try{if(n.nodeType===3){const p=n.parentNode;if(p&&/^(SCRIPT|STYLE|TEXTAREA)$/.test(p.nodeName))return;const v=n.data,r=tr(v);if(r!==v)n.data=r}
 else if(n.nodeType===1){if(/^(SCRIPT|STYLE|IFRAME)$/.test(n.nodeName))return;for(const a of ['title','placeholder','aria-label','alt']){const v=n.getAttribute&&n.getAttribute(a);if(v){const r=tr(v);if(r!==v)n.setAttribute(a,r)}}n.childNodes.forEach(esNode)}}catch(e){}}
function esStart(){esBuild();document.documentElement.lang='es';esNode(document.body);new MutationObserver(ms=>{for(const m of ms){if(m.type==='characterData')esNode(m.target);else m.addedNodes.forEach(esNode)}}).observe(document.body,{childList:true,subtree:true,characterData:true})}
function setLang(l){M.set.lang=l==='es'?'es':'en';mSave();location.reload()}
if(LANG==='es')esStart();

setTimeout(()=>{tmSync();mxSync();dcEnsure();checkAch();claimNewLevelItems();checkQuests();paintChip();fxSync();petSync();trailSync();applyExtras()},700);
